create schema private;

grant usage on schema private to authenticated;

create function private.is_self(p_uid uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from auth.users u where u.id = p_uid)
$$;

create function private.friends_with(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.friendships f
    where ((f.requester_id = a and f.addressee_id = b) or (f.requester_id = b and f.addressee_id = a))
      and f.status = 'accepted'
  )
$$;

create function private.friend_requester(p_uid uuid) returns uuid
language sql stable security definer set search_path = ''
as $$
  select f.requester_id from public.friendships f
  where f.addressee_id = p_uid and f.status = 'pending'
$$;

create function private.friend_addressee(p_uid uuid) returns uuid
language sql stable security definer set search_path = ''
as $$
  select f.requester_id from public.friendships f
  where f.addressee_id = p_uid and f.status = 'pending'
$$;

alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create policy friendships_select on public.friendships
  for select to authenticated
  using (
    requester_id = private.friend_requester(auth.uid())
    or addressee_id = private.friend_addressee(auth.uid())
  );

create policy friendships_insert on public.friendships
  for insert to authenticated
  with check (
    status = 'pending'
    and requester_id <> addressee_id
    and private.friend_requester(auth.uid()) is null
  );

create policy friendships_update on public.friendships
  for update to authenticated
  using (status = 'pending' and addressee_id = private.friend_addressee(auth.uid()))
  with check (status = 'accepted');

create policy friendships_delete on public.friendships
  for delete to authenticated
  using (requester_id = private.friend_requester(auth.uid()) or addressee_id = private.friend_addressee(auth.uid()));

create policy posts_select on public.posts
  for select to authenticated
  using (
    private.is_self(author_id)
    or private.friends_with(auth.uid(), author_id)
    or audience = 'public'
  );

create policy posts_insert on public.posts
  for insert to authenticated
  with check (
    private.is_self(author_id)
    and private.is_self(auth.uid())
  );

create policy posts_update on public.posts
  for update to authenticated
  using (private.is_self(author_id) and private.is_self(auth.uid()))
  with check (private.is_self(author_id) and private.is_self(auth.uid()));

create policy posts_delete on public.posts
  for delete to authenticated
  using (private.is_self(author_id) and private.is_self(auth.uid()));
