as $$
  select exists (
    select 1 from public.friendships f
    where ((f.requester_id = a and f.addressee_id = b) or (f.requester_id = b and f.addressee_id = a))
      and f.status = 'accepted'
  )
$$;

create function private.friend_request_pending(p_requester uuid, p_addressee uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.friendships f
    where f.requester_id = p_requester
      and f.addressee_id = p_addressee
      and f.status = 'pending'
  )
$$;

create function private.friend_request_acceptable(p_requester uuid, p_addressee uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select (
    select private.friend_request_pending(p_requester, p_addressee)
  )
$$;

alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create policy friendships_select on public.friendships
  for select to authenticated
  using (
    requester_id = auth.uid()
    or addressee_id = auth.uid()
    or private.friends_with(auth.uid(), requester_id)
    or private.friends_with(auth.uid(), addressee_id)
  );

create policy friendships_insert on public.friendships
  for insert to authenticated
  with check (
    requester_id = auth.uid()
    and status = 'pending'
    and addressee_id <> requester_id
    and private.friend_request_pending(requester_id, addressee_id) is false
  );

create policy friendships_update on public.friendships
  for update to authenticated
  using (private.friend_request_acceptable(requester_id, addressee_id))
  with check (status = 'accepted');

create policy friendships_delete on public.friendships
  for delete to authenticated
  using (
    requester_id = auth.uid()
    or addressee_id = auth.uid()
  );

create policy posts_select on public.posts
  for select to authenticated
  using (
    audience = 'public'
    or author_id = auth.uid()
    or private.friends_with(auth.uid(), author_id)
  );

create policy posts_insert on public.posts
  for insert to authenticated
  with check (
    audience in ('public', 'friends', 'only_me')
    and (
      audience = 'public'
      or audience = 'only_me'
      or private.friends_with(auth.uid(), author_id)
    )
  );

create policy posts_update on public.posts
  for update to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy posts_delete on public.posts
  for delete to authenticated
  using (author_id = auth.uid());
