language sql stable security definer set search_path = ''
as $$
  select coalesce(
    (select f.requester_id from public.friendships f where f.addressee_id = p_uid and f.status = 'pending'),
    (select f.addressee_id from public.friendships f where f.requester_id = p_uid and f.status = 'pending')
  )
$$;

