    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.unit_building_id(p_unit_id bigint)
returns bigint
language sql
stable
as $$
  select u.building_id
  from public.units u
  where u.id = p_unit_id
  limit 1;
$$;

create or replace function public.request_ownership(p_request_id bigint)
returns table (unit_id bigint, created_by uuid) language sql stable security definer set search_path = public as $$
  select r.unit_id, r.created_by
  from public.requests r
  where r.id = p_request_id;
$$;

create or replace function public.request_photos_ownership(p_request_id bigint)
returns table (request_id bigint) language sql stable security definer set search_path = public as $$
  select rp.request_id
  from public.request_photos rp
  where rp.request_id = p_request_id;
$$;

