  for insert to authenticated
  with check (created_by = auth.uid() and status = 'open' and public.is_resident(unit_id));

create policy requests_update on public.requests
  for update to authenticated
  using (public.is_building_staff(public.unit_building_id(unit_id)))
  with check (public.is_building_staff(public.unit_building_id(unit_id)) and status in ('open', 'in_progress', 'done'));

