returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.building_staff s
    join public.units u on u.building_id = s.building_id
    where u.id = p_unit_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.request_can_be_seen(p_request_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.requests r
    join public.units u on u.id = r.unit_id
    where r.id = p_request_id
      and (public.is_resident(r.unit_id) or public.has_building_access(r.unit_id))
  );
$$;

