on public.residents
for select
to authenticated
using (user_id = auth.uid());

create policy requests_select
on public.requests
for select
to authenticated
using (public.request_can_be_seen(id));

create policy requests_insert
on public.requests
for insert
to authenticated
with check (
  created_by = auth.uid()
  and status = 'open'
  and public.request_can_be_seen(id)
);

create policy requests_update
on public.requests
for update
to authenticated
using (public.request_can_be_seen(id))
with check (
  public.request_can_be_seen(id)
  and (
    public.is_resident(unit_id)
    or public.has_building_access(unit_id)
  )
);

