  if public.is_supervisor() then
    return new;
  end if;

  if public.is_support_agent() then
    if old.region is distinct from public.get_agent_region() then
      raise exception 'customers: cannot insert customer outside of your assigned region';
    end if;
  end if;

  new.region := coalesce(public.get_agent_region(), old.region);
  new.full_name := old.full_name;
  new.email_masked := 'a***@' || split_part(old.email, '@', 2);
  new.phone_masked := lpad(right(old.phone, 4), 6, '*'::text);
  new.phone := old.phone;

  return new;
end
