returns trigger
language plpgsql
set search_path = public
as $$
begin
  if public.is_supervisor() then
    return new;
  end if;

  if public.is_support_agent() then
    if old.region is distinct from public.get_agent_region() then
      raise exception 'support_customers: unauthorized region';
    end if;
    return old;
  end if;

  return new;
end
$$;

