  c.id,
  c.region,
  c.full_name,
  case
    when c.email ~ '^[^@]+@' then c.email[1] || '***@' || split_part(c.email, '@', 2)
    else c.email
  end as email_masked,
  case
    when c.phone ~ '^[0-9]{6}[0-9]{4}$' then '******' || right(c.phone, 4)
    else c.phone
  end as phone_masked
from public.customers c
where
  public.is_supervisor()
  or (public.is_support_agent() and c.region = public.get_agent_region());

