alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create or replace function public.is_auction_open(p_auction_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
  );
$$;

create or replace function public.is_seller(p_auction_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.seller_id = auth.uid()
  );
$$;

create or replace function public.is_bidder_on_auction(p_auction_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.bids b
    where b.auction_id = p_auction_id
      and b.bidder_id = auth.uid()
  );
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions%rowtype;
  v_highest numeric;
  v_increment numeric;
  v_min numeric;
  v_bidder uuid := auth.uid();
begin
  if v_bidder is null then
    raise exception 'not authenticated';
  end if;

  if not public.is_auction_open(p_auction_id) then
    raise exception 'auction is not open';
  end if;

  if public.is_seller(p_auction_id) then
    raise exception 'seller cannot bid on own auction';
  end if;

  select a.*, a.highest_bid, a.min_increment
  into v_auction, v_highest, v_increment
  from public.auctions a
  where a.id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if p_amount < v_auction.starting_price then
    raise exception 'bid below starting price';
  end if;

  if v_highest is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid below starting price';
    end if;
  else
    if p_amount <= v_highest then
      raise exception 'bid not above current highest';
    end if;
    if p_amount < v_highest + v_increment then
      raise exception 'bid below minimum increment';
    end if;
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_bidder
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder, p_amount, now());

  return p_amount;
end;
$$;

create policy auctions_select on public.auctions
for select
to authenticated
using (true);

create policy bids_select on public.bids
for select
to authenticated
using (bidder_id = auth.uid() or public.is_seller(auction_id));

create policy bids_insert on public.bids
for insert
to authenticated
with check (bidder_id = auth.uid());

revoke all on public.auctions from anon;
revoke all on public.bids from anon;

revoke all on public.auctions from authenticated;
grant select on public.auctions to authenticated;

revoke all on public.bids from authenticated;
grant select, insert on public.bids to authenticated;

revoke all on function public.is_auction_open(bigint) from public;
revoke all on function public.is_seller(bigint) from public;
revoke all on function public.is_bidder_on_auction(bigint) from public;
revoke all on function public.place_bid(bigint, numeric) from public;

