create or replace function public.is_auction_open(p_auction_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.ends_at > now()
  );
$$;

create or replace function public.is_seller_bid(p_auction_id bigint, p_bidder_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and a.seller_id = p_bidder_id
  );
$$;

create or replace function public.bid_minimum(p_auction_id bigint, p_amount numeric)
returns boolean
language sql
stable
as $$
  select (
    select case
      when coalesce(
        (select highest_bid from public.auctions a where a.id = p_auction_id),
        (select a.starting_price from public.auctions a where a.id = p_auction_id)
      ) is null
        then p_amount >= (select a.starting_price from public.auctions a where a.id = p_auction_id)
        else p_amount >= (
          select a.highest_bid + a.min_increment
          from public.auctions a
          where a.id = p_auction_id
        )
    end
  );
$$;

create policy auctions_select
on public.auctions
for select
to authenticated
using (true);

create policy bids_select
on public.bids
for select
to authenticated
using (
  bidder_id = auth.uid()
  or public.is_seller_bid(auction_id, auth.uid())
);

create policy place_bid
on public.bids
for insert
to authenticated
with check (
  public.is_auction_open(auction_id)
  and auth.uid() is distinct from (select seller_id from public.auctions a where a.id = auction_id)
  and public.bid_minimum(auction_id, amount)
);

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_min numeric;
  v_seller uuid;
  v_highest numeric;
  v_bidder uuid := auth.uid();
begin
  if v_bidder is null then
    raise exception 'Not authenticated';
  end if;

  if p_auction_id is null then
    raise exception 'Invalid auction';
  end if;

  if not exists (select 1 from public.auctions a where a.id = p_auction_id) then
    raise exception 'Auction not found';
  end if;

  select a.highest_bid, a.seller_id, a.ends_at, a.starting_price, a.min_increment
    into v_highest, v_seller, open, v_min, v_bidder
    from public.auctions a
    where a.id = p_auction_id
    for update;

  if open is false then
    raise exception 'Auction has ended';
  end if;

  if v_seller = v_bidder then
    raise exception 'Sellers cannot bid on their own auctions';
  end if;

  if v_highest is null then
    if p_amount < v_min then
      raise exception 'Bid is below starting price';
    end if;
  else
    if p_amount < v_highest + (select a.min_increment from public.auctions a where a.id = p_auction_id) then
      raise exception 'Bid is below highest bid plus minimum increment';
    end if;
  end if;

  update public.auctions
     set highest_bid = p_amount,
         highest_bidder = v_bidder
   where id = p_auction_id
     and exists (
       select 1
       from public.auctions a
       where a.id = p_auction_id
         and a.ends_at > now()
     );

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder, p_amount, now());

  return p_amount;
end;
$$;

