create or replace function public.can_bid(p_auction_id bigint, p_amount numeric)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and public.is_auction_open(p_auction_id)
      and (
        (a.highest_bid is null and p_amount >= a.starting_price)
        or (a.highest_bid is not null and p_amount >= a.highest_bid + a.min_increment)
      )
  );
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_bidder uuid := auth.uid();
  v_highest numeric;
begin
  if v_bidder is null then
    raise exception 'only signed-in users can place bids';
  end if;
  if not public.is_auction_open(p_auction_id) then
    raise exception 'auction is not open';
  end if;
  if public.is_auction_seller(p_auction_id) then
    raise exception 'sellers cannot bid on their own auctions';
  end if;
  if not public.can_bid(p_auction_id, p_amount) then
    raise exception 'bid amount is below the required minimum';
  end if;
  update public.auctions
     set highest_bid = p_amount,
         highest_bidder = v_bidder
   where id = p_auction_id;
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder, p_amount, now());
  select highest_bid into v_highest
  from public.auctions
  where id = p_auction_id;
  return v_highest;
end;
$$;

