  );
$$;

create or replace function public.bid_minimum(p_auction_id bigint, p_amount numeric)
returns numeric
language sql
stable
as $$
  select (
    select coalesce(a.highest_bid, 0) + a.min_increment
    from public.auctions a
    where a.id = p_auction_id
  )::numeric
  where exists (
    select 1
    from public.auctions a
    where a.id = p_auction_id
      and p_amount >= (
        select coalesce(a.highest_bid, 0) + a.min_increment
        from public.auctions a
        where a.id = p_auction_id
      )
  );
$$;

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result numeric := 0;
  v_bidder uuid := auth.uid();
  v_auction public.auctions%rowtype;
begin
  if v_bidder is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.auctions where id = p_auction_id) then
    raise exception 'auction % does not exist', p_auction_id;
  end if;

  if not public.is_auction_open(p_auction_id) then
    raise exception 'auction % is closed', p_auction_id;
  end if;

  select * into v_auction from public.auctions where id = p_auction_id for update;

  if v_auction.seller_id = v_bidder then
    raise exception 'bidders cannot bid on their own auctions';
  end if;

  if p_amount < public.bid_minimum(p_auction_id, p_amount) then
    raise exception 'bid amount % is below the current minimum', p_amount;
  end if;

  update public.auctions
     set highest_bid = p_amount,
         highest_bidder = v_bidder
   where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder, p_amount, now());

  return v_auction.highest_bid;
end;
$$;

