    (select count(*)::integer from public.class_spots s where s.class_id = p_class_id and s.status = 'enrolled'),
    0
  );
$$;

create or replace function public.class_instructor(p_class_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.classes c
    where c.id = p_class_id and c.instructor_id = (select auth.uid())
  );
$$;

create or replace function public.class_spots_enforce_role()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_user uuid := (select auth.uid());
  v_role text := coalesce((select auth.role()), '');
begin
  if current_setting('request.jwt.claim.role', true) = 'service_role' then
    return new;
  end if;

  if new.class_id is distinct from old.class_id then
    if tg_op = 'INSERT' and v_role not in ('service_role', 'instructor', 'teacher') then
      raise exception 'class_id cannot be changed';
    end if;
    if tg_op = 'DELETE' and v_role not in ('service_role', 'instructor', 'teacher') then
      raise exception 'class_id cannot be changed';
    end if;
    return new;
  end if;

  if v_role not in ('service_role', 'instructor', 'teacher') then
    if tg_op = 'INSERT' then
      if new.user_id is distinct from v_user then
        raise exception 'spot user_id must match the signer';
      end if;
    elsif tg_op = 'UPDATE' then
      if new.user_id is distinct from v_user then
        raise exception 'spot user_id cannot be changed';
      end if;
      if new.status is distinct from old.status then
        if old.status = 'enrolled' and new.status = 'enrolled' then
          raise exception 'cannot change an enrolled spot to enrolled';
        elsif old.status = 'waitlisted' and new.status = 'waitlisted' then
          raise exception 'cannot move a waitlisted spot to waitlisted';
        elsif old.status = 'enrolled' and new.status = 'waitlisted' then
          raise exception 'cannot move an enrolled spot to waitlisted';
        elsif old.status = 'waitlisted' and new.status = 'enrolled' then
          if public.classes_enrollment_capacity(new.class_id) >= public.classes.capacity then
            raise exception 'class is full';
          end if;
        else
          raise exception 'invalid status transition';
        end if;
      end if;
    elsif tg_op = 'DELETE' then
      if old.status not in ('enrolled', 'waitlisted') then
        raise exception 'invalid spot status';
      end if;
    end if;
  else
    if tg_op = 'INSERT' then
      if new.user_id is distinct from v_user and public.class_instructor(new.class_id) then
        raise exception 'instructors may only insert spots for themselves';
      end if;
      if public.classes_enrollment_capacity(new.class_id) >= public.classes.capacity then
        raise exception 'class is full';
      end if;
    elsif tg_op = 'UPDATE' then
      if new.status not in ('enrolled', 'waitlisted') then
        raise exception 'invalid spot status';
      end if;
      if old.status = 'enrolled' and new.status = 'enrolled' then
        raise exception 'cannot change an enrolled spot to enrolled';
      elsif old.status = 'waitlisted' and new.status = 'waitlisted' then
        raise exception 'cannot move a waitlisted spot to waitlisted';
      elsif old.status = 'enrolled' and new.status = 'waitlisted' then
        raise exception 'cannot move an enrolled spot to waitlisted';
      elsif old.status = 'waitlisted' and new.status = 'enrolled' then
        if public.classes_enrollment_capacity(new.class_id) >= public.classes.capacity then
          raise exception 'class is full';
        end if;
      end if;
    elsif tg_op = 'DELETE' then
      if old.status not in ('enrolled', 'waitlisted') then
        raise exception 'invalid spot status';
      end if;
    end if;
  end if;

  return new;
end;
$$;

